{"command":"cd /Users/michelkerkmeester/worktrees/public/315-frontend-reference-restructure && for f in .skilled/skills/cli-external-orchestration/cli-opencode/README.md .skilled/skills/cli-external-orchestration/cli-opencode/SKILL.md .skilled/skills/cli-external-orchestration/cli-opencode/assets/prompt-quality-card.md .skilled/skills/cli-external-orchestration/cli-opencode/assets/prompt-templates.md .skilled/skills/cli-external-orchestration/cli-opencode/references/*.md; do echo "=== $f"; JEV_FEATURES=0 python3 -B .skilled/skills/sk-doc/scripts/validate_document.py "$f" --json 2>/dev/null | python3 -c 'import json,sys
try:
 d=json.load(sys.stdin)
except Exception as e:
 print("JSONERR",e); sys.exit()
ws=[w for w in d.get("warnings",[]) if str(w.get("code","")).startswith("render") or "render" in json.dumps(w)]
print(json.dumps(d.get("warnings",[]),indent=1)[:3000] if d.get("warnings") else "no warnings")
'; done"}
